abstract class AutoRoutine {
    fun run() {
        drivePhase()
        actionPhase()
    }

    abstract fun drivePhase()
    abstract fun actionPhase()
}

class ScoreAuto : AutoRoutine() {
    override fun drivePhase() {
        println("Driving to scoring zone")
    }

    override fun actionPhase() {
        println("Scoring game piece")
    }
}

