import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDrivePhase() {
        val auto = ScoreAuto()
        val output = captureOutput { auto.drivePhase() }
        Assert.assertEquals("Driving to scoring zone", output.trim())
    }

    @Test
    fun testActionPhase() {
        val auto = ScoreAuto()
        val output = captureOutput { auto.actionPhase() }
        Assert.assertEquals("Scoring game piece", output.trim())
    }

    @Test
    fun testRunCallsBothInOrder() {
        val auto = ScoreAuto()
        val output = captureOutput { auto.run() }
        val lines = output.trim().split("\n")
        Assert.assertEquals(2, lines.size)
        Assert.assertEquals("Driving to scoring zone", lines[0])
        Assert.assertEquals("Scoring game piece", lines[1])
    }

    @Test
    fun testIsAutoRoutine() {
        val auto = ScoreAuto()
        Assert.assertTrue(auto is AutoRoutine)
    }
}

fun captureOutput(block: () -> Unit): String {
    val stream = java.io.ByteArrayOutputStream()
    val ps = java.io.PrintStream(stream)
    val old = System.out
    System.setOut(ps)
    block()
    System.setOut(old)
    return stream.toString()
}
